let repositoryVisibleFiles: Set<string> | undefined;

function getRepositoryVisibleFiles(): Set<string> {
  if (repositoryVisibleFiles) return repositoryVisibleFiles;
  const output = execFileSync("git", ["ls-files", "--cached", "--others", "--exclude-standard", "-z"], {
    cwd: REPO_ROOT,
    encoding: "utf8",
  });
  repositoryVisibleFiles = new Set(
    output
      .split("\0")
      .filter(Boolean)
      .map((file) => normalizePath(file)),
  );
  return repositoryVisibleFiles;
}

function isRepositoryVisible(repoPath: string): boolean {
  return getRepositoryVisibleFiles().has(normalizePath(repoPath));
}

